  ('column', 'guide', '이민비자·영주권 인터뷰, 공적부조 관련 준비사항', array['해외 대사관의 공적부조 질문지로 살펴보는 인터뷰 준비. I-864와 세금보고서만으로는 부족할 수 있습니다.']::text[], '', array['green']::text[], array['영주권 일반']::text[], 'https://blog.naver.com/hkimlaw/224448694402', 'blog', 'published', (timestamp '2026-10-21 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-10-21 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
