  ('column', 'qna', '영구영주권(정식영주권) 승인 없이 시민권 신청?', array['결혼 2년이 되기 전에 받은 조건부 영주권. I-751 승인 전에 시민권을 신청할 수 있을까요?']::text[], '', array['citizen', 'green']::text[], array['시민권', '가족이민']::text[], 'https://blog.naver.com/hkimlaw/224433687456', 'blog', 'published', (timestamp '2026-10-07 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-10-07 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
