  ('news', 'court', 'Advance Parole로 재입국시 주의', array['14년 만에 뒤집힌 이민 판례. 불법체류 기록이 있다면 Advance Parole로 해외에 나가기 전에 꼭 확인하세요.']::text[], '', array['green', 'defense']::text[], array['영주권 일반', '웨이버']::text[], 'https://blog.naver.com/hkimlaw/224401430956', 'blog', 'published', (timestamp '2026-09-05 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-09-05 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('news', 'court', '트럼프의 원정출산 규제 - 연방법원에서 또 제동', array['8월 6일 서명된 원정출산 규제 행정명령(EO 14419)에 연방법원이 다시 제동을 걸었습니다.']::text[], '', array['nonimm']::text[], array['방문·무비자']::text[], 'https://blog.naver.com/hkimlaw/224399698192', 'blog', 'published', (timestamp '2026-09-03 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-09-03 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('column', 'qna', '취업이민 영주권을 진행하려고 하는데요', array['취업이민 대기자가 126만 명을 넘었다는 통계와 함께, 지금 취업이민을 시작할 때 따져 볼 점을 정리했습니다.']::text[], '', array['green']::text[], array['취업이민']::text[], 'https://blog.naver.com/hkimlaw/224399142829', 'blog', 'published', (timestamp '2026-09-03 09:00' at time zone 'America/Los_Angeles') - interval '1 minutes', (timestamp '2026-09-03 09:00' at time zone 'America/Los_Angeles') - interval '1 minutes'),
  ('column', 'case', '영주권 승인 사례 공유 - 10년의 기다림', array['오랫동안 함께 진행해 온 케이스가 10년 만에 영주권 승인으로 마무리됐습니다.']::text[], '', array['green']::text[], array['가족이민']::text[], 'https://blog.naver.com/hkimlaw/224398181738', 'blog', 'published', (timestamp '2026-09-02 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-09-02 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('column', 'guide', '비시민권자의 유권자 등록과 투표권 행사', array['시민권 신청자가 특히 조심해야 할 유권자 등록과 투표 기록 문제를 정리했습니다.']::text[], '', array['citizen']::text[], array['시민권']::text[], 'https://blog.naver.com/hkimlaw/224394657363', 'blog', 'published', (timestamp '2026-08-30 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-08-30 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('news', 'notice', '대사관 이민비자 인터뷰 잠정 중단', array['국무부 심사 정책 변화로 한국을 포함한 해외 대사관의 이민비자 인터뷰 일정이 늦어질 수 있습니다.']::text[], '', array['green']::text[], array['영주권 일반']::text[], 'https://blog.naver.com/hkimlaw/224392685991', 'blog', 'published', (timestamp '2026-08-28 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-08-28 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
