  ('column', 'case', '601 waiver 승인 사례 공유', array['오랜 취업이민과 가족초청 진행 끝에, 8월 21일 I-601 웨이버가 최종 승인됐습니다.']::text[], '', array['defense', 'green']::text[], array['웨이버']::text[], 'https://blog.naver.com/hkimlaw/224386188641', 'blog', 'published', (timestamp '2026-08-22 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-08-22 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('news', 'notice', 'DACA 갱신 지연 장기화', array['DACA 갱신 심사가 예상보다 크게 늦어지고 있습니다. 걱정되시는 분들이 확인할 점을 정리했습니다.']::text[], '', array['defense']::text[], array['이민구제']::text[], 'https://blog.naver.com/hkimlaw/224385111142', 'blog', 'published', (timestamp '2026-08-21 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-08-21 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('news', 'policy', '이민국 신청서류는 이제 온라인 접수만 가능', array['USCIS가 새 규정으로 이민 신청서를 온라인 접수로 바꿉니다. 두꺼운 서류봉투와 우편 접수가 사라질 전망입니다.']::text[], '', array['green', 'nonimm', 'citizen']::text[], array['서류 접수']::text[], 'https://blog.naver.com/hkimlaw/224385110375', 'blog', 'published', (timestamp '2026-08-21 09:00' at time zone 'America/Los_Angeles') - interval '1 minutes', (timestamp '2026-08-21 09:00' at time zone 'America/Los_Angeles') - interval '1 minutes'),
  ('news', 'policy', '유학생비자 최대 4년, D/S제도 폐지', array['국토안보부가 F-1·J-1·I 비자의 체류 방식을 바꿉니다. 학생비자 제도의 큰 전환점을 정리했습니다.']::text[], '', array['nonimm']::text[], array['학생·교환']::text[], 'https://blog.naver.com/hkimlaw/224384012947', 'blog', 'published', (timestamp '2026-08-20 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-08-20 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('news', 'policy', '새로운 Public Charge 규정 시행', array['7월 20일 발표된 공적부조(Public Charge) 규정이 영주권 심사의 중요한 기준으로 다시 떠올랐습니다.']::text[], '', array['green']::text[], array['영주권 일반']::text[], 'https://blog.naver.com/hkimlaw/224383967165', 'blog', 'published', (timestamp '2026-08-20 09:00' at time zone 'America/Los_Angeles') - interval '1 minutes', (timestamp '2026-08-20 09:00' at time zone 'America/Los_Angeles') - interval '1 minutes'),
  ('news', 'policy', '원정출산 단속 강화', array['원정출산 단속이 강화되면서 과거 미국에서 자녀를 출산한 분들의 문의가 늘고 있습니다.']::text[], '', array['nonimm']::text[], array['방문·무비자']::text[], 'https://blog.naver.com/hkimlaw/224381706972', 'blog', 'published', (timestamp '2026-08-18 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-08-18 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('news', 'policy', '트럼프 정부의 원정출산 제한 조치', array['트럼프 행정부가 원정출산(Birth Tourism)에 다시 강력한 제동을 걸었습니다.']::text[], '', array['nonimm']::text[], array['방문·무비자']::text[], 'https://blog.naver.com/hkimlaw/224379170832', 'blog', 'published', (timestamp '2026-08-15 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-08-15 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('column', 'view', 'RFE 없이 비자·영주권 신청서 거절', array['USCIS가 불완전한 신청서를 추가 서류 요청(RFE) 없이 바로 거절할 수 있도록 심사 기준을 강화했습니다.']::text[], '', array['green', 'nonimm']::text[], array['영주권 일반']::text[], 'https://blog.naver.com/hkimlaw/224379166216', 'blog', 'published', (timestamp '2026-08-15 09:00' at time zone 'America/Los_Angeles') - interval '1 minutes', (timestamp '2026-08-15 09:00' at time zone 'America/Los_Angeles') - interval '1 minutes'),
  ('column', 'guide', '글로벌 엔트리(Global Entry) 신청', array['프로디(Prodee) 등 과거 학교 등록 기록이 있는 분들이 글로벌 엔트리를 신청할 때 주의할 점입니다.']::text[], '', array['defense', 'citizen']::text[], array['과거 기록']::text[], 'https://blog.naver.com/hkimlaw/224376216607', 'blog', 'published', (timestamp '2026-08-12 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-08-12 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('column', 'guide', '유학생들의 취업이민 진행 시 유의사항', array['비이민 체류 제도가 바뀌는 지금, 유학생이 취업이민을 준비할 때 유의할 점을 정리했습니다.']::text[], '', array['nonimm', 'green']::text[], array['학생·교환', '취업이민']::text[], 'https://blog.naver.com/hkimlaw/224368351747', 'blog', 'published', (timestamp '2026-08-05 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-08-05 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('news', 'policy', 'Duration of Status(D/S) 제도의 폐지', array['F-1·J-1 비자에 수십 년간 유지된 D/S 제도를 없애는 국토안보부 최종 규정을 정리했습니다.']::text[], '', array['nonimm']::text[], array['학생·교환']::text[], 'https://blog.naver.com/hkimlaw/224353929877', 'blog', 'published', (timestamp '2026-07-22 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-07-22 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('news', 'bulletin', '2026년 8월 영주권 문호', array['8월에는 가족이민과 취업이민 모두 전반적으로 진전됐습니다.']::text[], '', array['green']::text[], array['가족이민', '취업이민']::text[], 'https://blog.naver.com/hkimlaw/224353917518', 'blog', 'published', (timestamp '2026-07-22 09:00' at time zone 'America/Los_Angeles') - interval '1 minutes', (timestamp '2026-07-22 09:00' at time zone 'America/Los_Angeles') - interval '1 minutes'),
  ('news', 'policy', '유학생 비자 체류 최대 4년', array['유학생(F-1)·교환방문(J-1)·외국 언론인(I) 비자에 대한 새 최종 규정이 발표됐습니다.']::text[], '', array['nonimm']::text[], array['학생·교환']::text[], 'https://blog.naver.com/hkimlaw/224349046925', 'blog', 'published', (timestamp '2026-07-17 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-07-17 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('news', 'notice', 'DACA 갱신 지연중', array['DACA 갱신 심사가 눈에 띄게 늦어지면서 많은 드리머(Dreamer)들이 불안해하고 있습니다.']::text[], '', array['defense']::text[], array['이민구제']::text[], 'https://blog.naver.com/hkimlaw/224324059248', 'blog', 'published', (timestamp '2026-06-23 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-06-23 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('news', 'bulletin', '2026년 7월 영주권 문호', array['7월 취업이민은 일부 순위에서 소폭 진전했지만, 전반적으로는 제한적인 움직임을 보였습니다.']::text[], '', array['green']::text[], array['가족이민', '취업이민']::text[], 'https://blog.naver.com/hkimlaw/224318641633', 'blog', 'published', (timestamp '2026-06-17 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-06-17 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('news', 'court', '전문직 취업비자 H1b 10만불 수수료는 위법', array['매사추세츠 연방지방법원이 6월 8일 H-1B 10만 달러 수수료를 위법으로 판단하고 효력을 무효화했습니다.']::text[], '', array['nonimm']::text[], array['취업·투자비자']::text[], 'https://blog.naver.com/hkimlaw/224310432249', 'blog', 'published', (timestamp '2026-06-09 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-06-09 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('column', 'guide', '영주권 신체검사는 이민국 지정 병원에서', array['최근 I-485 케이스에서 I-693 신체검사 관련 RFE가 잇따랐습니다. 지정 의사에게 받아야 하는 이유를 설명합니다.']::text[], '', array['green']::text[], array['영주권 일반']::text[], 'https://blog.naver.com/hkimlaw/224303275416', 'blog', 'published', (timestamp '2026-06-02 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-06-02 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('column', 'view', 'USCIS 메모 발표 후 이민국 인터뷰를 다녀왔습니다', array['새 정책 메모(PM-602-0199)가 나온 뒤 직접 다녀온 영주권 인터뷰 현장 이야기입니다.']::text[], '', array['green']::text[], array['영주권 일반']::text[], 'https://blog.naver.com/hkimlaw/224300604553', 'blog', 'published', (timestamp '2026-05-30 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-05-30 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('column', 'view', '새로운 영주권 정책 메모에 대한 향후 전망', array['미국 안에서 내는 영주권 신청에 관한 USCIS 정책 메모가 앞으로 어떤 영향을 줄지 전망했습니다.']::text[], '', array['green']::text[], array['영주권 일반']::text[], 'https://blog.naver.com/hkimlaw/224299580707', 'blog', 'published', (timestamp '2026-05-29 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-05-29 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('news', 'policy', 'Day-1 CPT 학생신분 전환', array['USCIS가 Day-1 CPT 프로그램을 이용한 F-1 신분 변경을 매우 엄격하게 심사하고 있습니다.']::text[], '', array['nonimm']::text[], array['학생·교환']::text[], 'https://blog.naver.com/hkimlaw/224298512875', 'blog', 'published', (timestamp '2026-05-28 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-05-28 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('news', 'policy', '이민국(USCIS)의 발표된 메모와 향후 전망', array['USCIS가 새 정책 메모(PM-602-0199)로 미국 안에서 내는 영주권 신청에 대해 강한 입장을 밝혔습니다.']::text[], '', array['green']::text[], array['영주권 일반']::text[], 'https://blog.naver.com/hkimlaw/224294768946', 'blog', 'published', (timestamp '2026-05-24 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-05-24 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('news', 'bulletin', '2026년 6월 영주권 문호', array['6월 취업이민은 5월에 이어 사실상 동결됐고, 가족이민은 일부 진전이 있었습니다.']::text[], '', array['green']::text[], array['가족이민', '취업이민']::text[], 'https://blog.naver.com/hkimlaw/224288076684', 'blog', 'published', (timestamp '2026-05-17 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-05-17 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('news', 'policy', 'H1b 최저임금 인상 추진중', array['노동부가 H-1B와 취업이민(PERM)에 적용되는 통상임금 기준을 크게 올리는 규정을 추진하고 있습니다.']::text[], '', array['nonimm', 'green']::text[], array['취업·투자비자', '취업이민']::text[], 'https://blog.naver.com/hkimlaw/224283504524', 'blog', 'published', (timestamp '2026-05-12 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-05-12 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('news', 'policy', 'F1 (유학생비자)의 체류 기간', array['트럼프 행정부가 유학생 체류 제도를 다시 손질할 가능성이 제기되면서 걱정이 커지고 있습니다.']::text[], '', array['nonimm']::text[], array['학생·교환']::text[], 'https://blog.naver.com/hkimlaw/224282424157', 'blog', 'published', (timestamp '2026-05-12 09:00' at time zone 'America/Los_Angeles') - interval '1 minutes', (timestamp '2026-05-12 09:00' at time zone 'America/Los_Angeles') - interval '1 minutes'),
  ('news', 'bulletin', '2026년 5월 영주권 문호', array['5월 취업이민은 4월의 큰 진전과 달리 대부분 동결되거나 조금만 움직였습니다.']::text[], '', array['green']::text[], array['가족이민', '취업이민']::text[], 'https://blog.naver.com/hkimlaw/224255250071', 'blog', 'published', (timestamp '2026-04-17 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-04-17 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('news', 'notice', '전문직 취업비자(H1b) 추첨 결과 통보 시작', array['2027 회계연도(FY 2027) H-1B 사전 등록 추첨 결과 통보가 시작됐습니다.']::text[], '', array['nonimm']::text[], array['취업·투자비자']::text[], 'https://blog.naver.com/hkimlaw/224235094047', 'blog', 'published', (timestamp '2026-03-31 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-03-31 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('column', 'case', 'ESTA(무비자) 입국 후 시민권자와 결혼 - 영주권 승인', array['ESTA로 입국해 약 3개월 뒤 시민권자와 결혼한 의뢰인의 배우자 초청이 빠르게 승인됐습니다.']::text[], '', array['green']::text[], array['가족이민']::text[], 'https://blog.naver.com/hkimlaw/224229932712', 'blog', 'published', (timestamp '2026-03-26 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-03-26 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('column', 'case', '화학공학 석사학위 소지자 NIW 승인', array['긴 심사 끝에 프리미엄 처리(Premium Processing)로 승인된 국가이익면제(NIW) 사례입니다.']::text[], '', array['green']::text[], array['취업이민']::text[], 'https://blog.naver.com/hkimlaw/224222962512', 'blog', 'published', (timestamp '2026-03-20 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-03-20 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('news', 'bulletin', '2026년 4월 영주권 문호', array['4월에는 가족이민과 취업이민 모두 큰 폭으로 진전됐고, 특히 EB-3가 눈에 띄게 움직였습니다.']::text[], '', array['green']::text[], array['가족이민', '취업이민']::text[], 'https://blog.naver.com/hkimlaw/224221685077', 'blog', 'published', (timestamp '2026-03-19 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-03-19 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('column', 'case', '20년 동안 가족을 돌본 아들, I-601 Waiver 승인 사례', array['3월 11일 승인된 I-601 웨이버 사례입니다. 전날 인터뷰에 함께 다녀왔습니다.']::text[], '', array['defense']::text[], array['웨이버']::text[], 'https://blog.naver.com/hkimlaw/224213279773', 'blog', 'published', (timestamp '2026-03-12 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2026-03-12 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes'),
  ('column', 'case', '프로디 기록이 있는 시민권자 배우자, 영주권 승인', array['과거 프로디(학교) 등록 기록이 있던 시민권자 배우자의 영주권 승인 사례입니다.']::text[], '', array['green', 'defense']::text[], array['가족이민', '과거 기록']::text[], null, 'cafe', 'published', (timestamp '2023-02-10 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes', (timestamp '2023-02-10 09:00' at time zone 'America/Los_Angeles') - interval '0 minutes');
